     3	/// App entry point. A small launcher window opens the full immersive space, which
     4	/// IS the experience (no passthrough). Spec: §1, §7.
     5	@main
     6	struct FloatApp: App {
     7	    @State private var model = AppModel()
     8	
     9	    var body: some Scene {
    10	        WindowGroup(id: "launcher") {
    11	            LauncherView()
    12	                .environment(model)
    13	        }
    14	        .windowResizability(.contentSize)
    15	
    16	        // Reading panel (Kindle Cloud Reader etc.) as its own window — the system gives it a
    17	        // drag bar + resize + eye-level placement, so you can put it wherever you're lying.
    18	        WindowGroup(id: "reader") {
    19	            ReaderPanelView()
    20	        }
    21	        .defaultSize(width: 640, height: 900)
    22	
    23	        // Scene picker (§7a) — its own window so it can be opened from inside the immersive
    24	        // space and left floating while iterating on a specific sky.
    25	        WindowGroup(id: "scenes") {
    26	            SceneSelectorView()
    27	                .environment(model)
    28	        }
    29	        .defaultSize(width: 520, height: 640)
    30	
    31	        // Entertainment sub-menu — Kindle / Music / Video.
    32	        WindowGroup(id: "entertainment") {
    33	            EntertainmentMenuView()
    34	        }
    35	        .defaultSize(width: 400, height: 480)
    36	
    37	        ImmersiveSpace(id: AppModel.immersiveSpaceID) {
    38	            ImmersiveView()
    39	                .environment(model)
    40	        }
    41	        // §1 — full immersion, everything else out of the way.
    42	        .immersionStyle(selection: .constant(.full), in: .full)
    43	    }
    44	}
=====Float/App/AppModel.swift=====
     1	import SwiftUI
     2	import RealityKit
     3	
     4	/// App-wide observable state. The generated L1–L4 universe was retired in favour of a fixed
     5	/// library of pre-rendered stereo skies, so this is now just: which sky is showing, plus the
     6	/// hooks the immersive scene needs to swap it. Spec: §7a (scene selection), §7e (saved Places).
     7	@Observable
     8	@MainActor
     9	final class AppModel {
    10	    static let immersiveSpaceID = "FloatSpace"
    11	
    12	    enum ImmersionState { case closed, opening, open }
    13	    var immersion: ImmersionState = .closed
    14	
    15	    /// Index of the current sky in `SpatialImageEnvironment.catalog`. Restored across
    16	    /// launches by NAME (not index) so catalog additions/reorders don't shift the selection.
    17	    var currentScene: Int = 0
    18	
    19	    private static let lastSceneKey = "lastSceneName"
    20	
    21	    init() {
    22	        if let name = UserDefaults.standard.string(forKey: Self.lastSceneKey),
    23	           let idx = SpatialImageEnvironment.catalog.firstIndex(where: { $0.name == name }) {
    24	            currentScene = idx
    25	        }
    26	    }
    27	
    28	    /// Global animation clock (§5, foundational). Retained for future slow motion (e.g. a
    29	    /// gentle backdrop yaw); nothing reads it while the scene is a static sphere.
    30	    let clock = AnimationClock()
    31	
    32	    /// Saved "Places" (§7e).
    33	    var savedLocations: [SavedLocation] = []
    34	
    35	    /// Set by ImmersiveView once the scene builds.
    36	    var sceneContainer: Entity?   // persistent container
    37	    var sceneRoot: Entity?        // the SpatialImageEnvironment sphere container
    38	    var whiteout: Entity?         // §7b flash overlay
    39	
    40	    // MARK: - Scene selection
    41	
    42	    /// Show a specific sky by catalog index, masked by the §7b whiteout flash.
    43	    func selectScene(_ index: Int) {
    44	        let n = SpatialImageEnvironment.catalog.count
    45	        guard n > 0 else { return }
    46	        let idx = ((index % n) + n) % n
    47	        currentScene = idx
    48	        UserDefaults.standard.set(
    49	            SpatialImageEnvironment.catalog[idx].name, forKey: Self.lastSceneKey)
    50	        maskedSwap { [weak self] in self?.applyScene(idx) }
    51	    }
    52	
    53	    /// Jump to a random *different* sky. Uses a shuffle bag so every sky is visited once
    54	    /// before any repeat (independent random draws clustered on a few). No determinism
    55	    /// requirement here — this is a user action, not generation (§5 applied to the retired
    56	    /// generated scene).
    57	    func randomScene() {
    58	        let n = SpatialImageEnvironment.catalog.count
    59	        guard n > 1 else { if n == 1 { selectScene(0) }; return }
    60	        if sceneBag.isEmpty {
    61	            var bag = Array(0..<n).shuffled()
    62	            if bag.last == currentScene { bag.swapAt(0, n - 1) }   // no immediate repeat
    63	            sceneBag = bag
    64	        }
    65	        selectScene(sceneBag.removeLast())
    66	    }
    67	
    68	    private var sceneBag: [Int] = []
    69	
    70	    /// Load the sky into the sphere. Falls through to the mono skybox if the stereo material
    71	    /// or an eye can't load (SpatialImageEnvironment handles that).
    72	    private func applyScene(_ index: Int) {
    73	        guard let sceneRoot else { return }
    74	        Task { @MainActor in await SpatialImageEnvironment.load(index: index, into: sceneRoot) }
    75	    }
    76	
    77	    /// Run `swap` under the peak of the §7b whiteout flash. Applies immediately if the overlay
    78	    /// isn't mounted yet (e.g. a scene chosen from the launcher before entering the space).
    79	    private func maskedSwap(_ swap: @escaping @MainActor () -> Void) {
    80	        guard let whiteout else { swap(); return }
    81	        if whiteout.components[WhiteoutComponent.self]?.active == true { return }
    82	        var c = whiteout.components[WhiteoutComponent.self] ?? WhiteoutComponent()
    83	        c.active = true; c.elapsed = 0
    84	        whiteout.components.set(c)
    85	        Task { @MainActor in
    86	            try? await Task.sleep(for: .seconds(0.30))
    87	            swap()
    88	        }
    89	    }
    90	}
    91	
    92	/// Launcher — the flat window that opens the immersive space and gives the three top-level
    93	/// actions: a random sky, the scene picker, and the Entertainment sub-menu (Kindle / Music /
    94	/// Video). Everything scene-related now targets the single spatial-image system.
    95	struct LauncherView: View {
    96	    @Environment(AppModel.self) private var model
    97	    @Environment(\.openImmersiveSpace) private var openImmersiveSpace
    98	    @Environment(\.dismissImmersiveSpace) private var dismissImmersiveSpace
    99	    @Environment(\.openWindow) private var openWindow
   100	
   101	    var body: some View {
   102	        VStack(spacing: 16) {
   103	            Text("Float").font(.extraLargeTitle)
   104	            Text("Step into deep space.").foregroundStyle(.secondary)
   105	
   106	            Button("Enter") {
   107	                Task {
   108	                    model.immersion = .opening
   109	                    _ = await openImmersiveSpace(id: AppModel.immersiveSpaceID)
   110	                    model.immersion = .open
   111	                }
   112	            }
   113	            .buttonStyle(.borderedProminent)
   114	            .disabled(model.immersion != .closed)
   115	
   116	            Button("Random Scene", systemImage: "shuffle") { model.randomScene() }
   117	                .buttonStyle(.bordered)
   118	
   119	            Button("Scenes…", systemImage: "square.grid.2x2") { openWindow(id: "scenes") }
   120	                .buttonStyle(.bordered)
   121	
   122	            Button("Entertainment", systemImage: "play.rectangle.on.rectangle") {
   123	                openWindow(id: "entertainment")
   124	            }
   125	            .buttonStyle(.bordered)
   126	
   127	            Button("Exit", systemImage: "power", role: .destructive) {
   128	                // Leave cleanly: dismiss the immersive space first, then terminate. A hard
   129	                // exit is fine for a single-user sideloaded app (no App Store review).
   130	                Task {
   131	                    if model.immersion == .open { await dismissImmersiveSpace() }
   132	                    exit(0)
   133	                }
   134	            }
   135	            .buttonStyle(.bordered)
   136	            .padding(.top, 8)
   137	        }
   138	        .padding(40)
   139	        .task {
   140	            // Launch straight into the environment — the menu stays up for Scenes/Exit but
   141	            // shouldn't gate entry. (The in-scene control panel's hand-tracking reveal is
   142	            // still stubbed, so the launcher window must keep existing as the fallback UI.)
   143	            guard model.immersion == .closed else { return }
   144	            model.immersion = .opening
   145	            _ = await openImmersiveSpace(id: AppModel.immersiveSpaceID)
   146	            model.immersion = .open
   147	        }
   148	    }
   149	}
