     1	import SwiftUI
     2	import UIKit
     3	
     4	/// Scene picker — the one selection surface now that every scene is a stereo sky. Grounded
     5	/// skies (real horizon, vertigo mitigation) are grouped apart from deep space. Each entry
     6	/// shows a thumbnail (Backdrop/Thumbnails/<name>.jpg). Its own window so it can float open
     7	/// inside the immersive space.
     8	struct SceneSelectorView: View {
     9	    @Environment(AppModel.self) private var model
    10	    @State private var query = ""
    11	
    12	    private let columns = [GridItem(.adaptive(minimum: 200), spacing: 16)]
    13	
    14	    private func scenes(grounded: Bool) -> [(index: Int, scene: SpatialImageEnvironment.Scene)] {
    15	        SpatialImageEnvironment.catalog.enumerated()
    16	            .filter { $0.element.grounded == grounded }
    17	            .filter { query.isEmpty || $0.element.title.localizedCaseInsensitiveContains(query) }
    18	            .map { (index: $0.offset, scene: $0.element) }
    19	    }
    20	
    21	    var body: some View {
    22	        NavigationStack {
    23	            ScrollView {
    24	                LazyVGrid(columns: columns, spacing: 16) {
    25	                    section("Grounded", subtitle: "Real horizon — a fixed reference frame if floating brings on vertigo.",
    26	                            items: scenes(grounded: true))
    27	                    section("Deep Space", subtitle: nil, items: scenes(grounded: false))
    28	                }
    29	                .padding(20)
    30	            }
    31	            .navigationTitle("Scenes")
    32	            .searchable(text: $query, prompt: "Find a scene")
    33	        }
    34	        .frame(minWidth: 460, minHeight: 520)
    35	    }
    36	
    37	    @ViewBuilder
    38	    private func section(_ title: String, subtitle: String?,
    39	                         items: [(index: Int, scene: SpatialImageEnvironment.Scene)]) -> some View {
    40	        if !items.isEmpty {
    41	            Section {
    42	                ForEach(items, id: \.scene.id) { item in
    43	                    SceneTile(scene: item.scene,
    44	                              isCurrent: model.currentScene == item.index) {
    45	                        model.selectScene(item.index)
    46	                    }
    47	                }
    48	            } header: {
    49	                VStack(alignment: .leading, spacing: 2) {
    50	                    Text(title).font(.headline)
    51	                    if let subtitle { Text(subtitle).font(.caption).foregroundStyle(.secondary) }
    52	                }
    53	                .frame(maxWidth: .infinity, alignment: .leading)
    54	                .padding(.top, 8)
    55	            }
    56	        }
    57	    }
    58	}
    59	
    60	/// A single thumbnail tile. Loads Backdrop/Thumbnails/<name>.jpg from the bundle; shows a
    61	/// placeholder if it isn't there yet (e.g. before the batch conversion has produced it).
    62	private struct SceneTile: View {
    63	    let scene: SpatialImageEnvironment.Scene
    64	    let isCurrent: Bool
    65	    let action: () -> Void
    66	
    67	    private var thumbnail: UIImage? {
    68	        guard let url = Bundle.main.url(forResource: scene.name, withExtension: "jpg",
    69	                                        subdirectory: "Thumbnails")
    70	            ?? Bundle.main.url(forResource: scene.name, withExtension: "jpg")
    71	        else { return nil }
    72	        return UIImage(contentsOfFile: url.path)
    73	    }
    74	
    75	    var body: some View {
    76	        Button(action: action) {
    77	            VStack(alignment: .leading, spacing: 6) {
    78	                ZStack {
    79	                    if let img = thumbnail {
    80	                        Image(uiImage: img).resizable().aspectRatio(2, contentMode: .fit)
    81	                    } else {
    82	                        Rectangle().fill(.quaternary).aspectRatio(2, contentMode: .fit)
    83	                            .overlay(Image(systemName: "photo").foregroundStyle(.secondary))
    84	                    }
    85	                }
    86	                .clipShape(RoundedRectangle(cornerRadius: 10))
    87	                .overlay(alignment: .topTrailing) {
    88	                    if isCurrent {
    89	                        Image(systemName: "checkmark.circle.fill")
    90	                            .foregroundStyle(.tint).padding(6)
    91	                            .background(.thinMaterial, in: Circle()).padding(6)
    92	                    }
    93	                }
    94	                .overlay(RoundedRectangle(cornerRadius: 10)
    95	                    .strokeBorder(isCurrent ? Color.accentColor : .clear, lineWidth: 3))
    96	
    97	                Text(scene.title).font(.callout).lineLimit(1)
    98	            }
    99	        }
   100	        .buttonStyle(.plain)
   101	    }
   102	}
