     1	import SwiftUI
     2	import AVKit
     3	import PhotosUI
     4	
     5	/// Entertainment sub-menu (reached from the launcher's "Entertainment" button). Collects the
     6	/// non-scene activities: the Kindle reader (moved here from the launcher), music from the
     7	/// Music app, and a video picked from the user's photo/media library.
     8	struct EntertainmentMenuView: View {
     9	    @Environment(\.openWindow) private var openWindow
    10	    @Environment(\.openURL) private var openURL
    11	
    12	    @State private var pickedVideo: PhotosPickerItem?
    13	    @State private var videoURL: URL?
    14	    @State private var loadingVideo = false
    15	
    16	    var body: some View {
    17	        NavigationStack {
    18	            List {
    19	                Section("Read") {
    20	                    Button {
    21	                        openWindow(id: "reader")
    22	                    } label: {
    23	                        Label("Kindle", systemImage: "book")
    24	                    }
    25	                }
    26	
    27	                Section("Listen") {
    28	                    // Opens the Music app so the user can play their own library. Full in-app
    29	                    // MusicKit playback would need the MusicKit capability + authorization;
    30	                    // launching the app is the dependency-free option.
    31	                    Button {
    32	                        if let url = URL(string: "music://") { openURL(url) }
    33	                    } label: {
    34	                        Label("Music", systemImage: "music.note")
    35	                    }
    36	                }
    37	
    38	                Section("Watch") {
    39	                    // User-selected media needs no photo-library entitlement.
    40	                    PhotosPicker(selection: $pickedVideo, matching: .videos) {
    41	                        Label(loadingVideo ? "Loading…" : "Video from Library",
    42	                              systemImage: "film")
    43	                    }
    44	                    if let videoURL {
    45	                        VideoPlayer(player: AVPlayer(url: videoURL))
    46	                            .frame(height: 260)
    47	                            .clipShape(RoundedRectangle(cornerRadius: 12))
    48	                    }
    49	                }
    50	            }
    51	            .navigationTitle("Entertainment")
    52	        }
    53	        .frame(minWidth: 360, minHeight: 440)
    54	        .onChange(of: pickedVideo) { _, item in
    55	            guard let item else { return }
    56	            loadingVideo = true
    57	            Task {
    58	                videoURL = try? await item.loadTransferable(type: PickedVideo.self)?.url
    59	                loadingVideo = false
    60	            }
    61	        }
    62	    }
    63	}
    64	
    65	/// Copies a picked video out of the Photos sandbox into a temp file AVPlayer can stream.
    66	private struct PickedVideo: Transferable {
    67	    let url: URL
    68	    static var transferRepresentation: some TransferRepresentation {
    69	        FileRepresentation(contentType: .movie) { video in
    70	            SentTransferredFile(video.url)
    71	        } importing: { received in
    72	            let dst = URL.temporaryDirectory.appendingPathComponent(
    73	                "float-video-" + received.file.lastPathComponent)
    74	            try? FileManager.default.removeItem(at: dst)
    75	            try FileManager.default.copyItem(at: received.file, to: dst)
    76	            return Self(url: dst)
    77	        }
    78	    }
    79	}
=====Float/Interaction/Interaction.swift=====
     1	import SwiftUI
     2	import RealityKit
     3	import ARKit
     4	import simd
     5	
     6	/// §7 — reveal gesture. Two thumb+index pinch/release cycles within ~350–450 ms.
     7	/// WARNING: a single pinch is the system "tap" — arm this only when gaze is off UI (§7).
     8	@MainActor
     9	final class DoublePinchDetector {
    10	    var onDoublePinch: (() -> Void)?
    11	
    12	    // Hysteresis thresholds (metres) so one slow pinch isn't read as two.
    13	    private let pinchOn: Float = 0.015
    14	    private let pinchOff: Float = 0.03
    15	    /// Max gap between the two pinch *releases* (§7: two cycles inside ~350–450 ms).
    16	    private let window: Double = 0.45
    17	
    18	    private var isPinched = false
    19	    private var lastReleaseTime: Double?
    20	
    21	    func ingest(thumbTip: SIMD3<Float>, indexTip: SIMD3<Float>, time: Double) {
    22	        let d = simd_distance(thumbTip, indexTip)
    23	        if isPinched {
    24	            guard d > pinchOff else { return }
    25	            isPinched = false
    26	            if let prev = lastReleaseTime, time - prev <= window {
    27	                lastReleaseTime = nil
    28	                onDoublePinch?()
    29	            } else {
    30	                lastReleaseTime = time
    31	            }
    32	        } else if d < pinchOn {
    33	            isPinched = true
    34	            // A first release too old to pair with the cycle starting now is stale.
    35	            if let prev = lastReleaseTime, time - prev > window { lastReleaseTime = nil }
    36	        }
    37	    }
    38	}
    39	
    40	/// §7 — the in-scene control panel (ViewAttachment). Trimmed to what the spatial-image app
    41	/// needs: a random-scene jump and save. (The old time-speed slider drove generated animation
    42	/// that no longer exists; the flick-an-asteroid interaction went with the asteroid layer.)
    43	struct ControlPanelView: View {
    44	    @Environment(AppModel.self) private var model
    45	
    46	    var body: some View {
    47	        VStack(spacing: 20) {
    48	            Button("Random Scene") { model.randomScene() }
    49	            Button("Save This Spot") {
    50	                // §7e capture current sceneName + thumbnail.
    51	            }
    52	        }
    53	        .padding(28)
    54	        .glassBackgroundEffect()
    55	        .frame(width: 320)
    56	    }
    57	}

